-- Read-only baseline extracted from TESTE on 2026-08-18.
-- Source: DBMS_METADATA supplied by the user; do not edit as deployment source.
CREATE OR REPLACE FORCE EDITIONABLE VIEW "TESTE"."AD_VGFFRPROD"
("CODPROD", "QTDPED", "SALDOEST") AS
SELECT P.CODPROD,
       COUNT(1) AS QTDPED,
       FNC_ESTCOMERCIAL_PRA(P.CODPROD) AS SALDOEST
  FROM AD_VGFRESEST P
 GROUP BY P.CODPROD
UNION
SELECT P.CODPROD,
       COUNT(1) AS QTDPED,
       FNC_ESTCOMERCIAL_PRA(P.CODPROD) AS SALDOEST
  FROM AD_VGFPROVEST P
 GROUP BY P.CODPROD;
